from rules import dependencies


def solve(data):
    packages = data['packages']
    names = sorted(packages)
    required = {}

    for name, bounds in data['roots'].items():
        if name not in packages:
            return {'error': 'unsatisfiable'}
        required.setdefault(name, []).append(tuple(bounds))

    best = None
    best_vector = None

    def allowed(version, constraints):
        return all((low is None or version >= low) and
                   (high is None or version <= high)
                   for low, high in constraints)

    def search(constraints, assigned):
        nonlocal best, best_vector

        for name, version in assigned.items():
            if not allowed(version, constraints[name]):
                return

        pending = [name for name in constraints if name not in assigned]
        if not pending:
            vector = tuple(assigned.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best = assigned.copy()
                best_vector = vector
            return

        name = min(pending)
        for row in sorted(packages[name],
                          key=lambda item: item['version'], reverse=True):
            version = row['version']
            if not allowed(version, constraints[name]):
                continue

            next_constraints = {
                key: value.copy() for key, value in constraints.items()
            }
            next_assigned = assigned.copy()
            next_assigned[name] = version
            valid = True

            for dep_name, dep_bounds in dependencies(row.get('deps', [])):
                if dep_name not in packages:
                    valid = False
                    break
                next_constraints.setdefault(dep_name, []).append(dep_bounds)
                if (dep_name in next_assigned and
                        not allowed(next_assigned[dep_name],
                                    next_constraints[dep_name])):
                    valid = False
                    break

            if valid:
                search(next_constraints, next_assigned)

    search(required, {})
    if best is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best}

def _bounds(value):
    if isinstance(value, (list, tuple)) and len(value) == 2:
        return tuple(value)
    if isinstance(value, int):
        return (value, value)
    return (None, None)


def _dependency(item):
    if isinstance(item, str):
        return item, (None, None)
    if isinstance(item, dict):
        name = item.get('name', item.get('package'))
        if name is not None:
            if 'range' in item:
                bounds = _bounds(item['range'])
            elif 'version' in item:
                bounds = _bounds(item['version'])
            elif 'min' in item or 'max' in item:
                bounds = (item.get('min'), item.get('max'))
            else:
                bounds = (None, None)
            return name, bounds
        if len(item) == 1:
            name, value = next(iter(item.items()))
            return name, _bounds(value)
    if isinstance(item, (list, tuple)) and item:
        name = item[0]
        if len(item) == 2:
            return name, _bounds(item[1])
        if len(item) >= 3:
            return name, (item[1], item[2])
    raise ValueError('invalid dependency')


def dependencies(items):
    for item in items:
        yield _dependency(item)
